    ["Give it here and Maywiki fix it right up."] = "Donne-le ici et Maywiki il te le répare tout de suite.",
    ["Sulhasa in southern Barrens wants you to clear out 7 Stormhide lizards and 7 Hecklefang Stalkers in the area so she can leave the tree safely."] = "Sulhasa, dans le sud des Tarides, veut que vous élimiez 7 lézards Peau-d'orage et 7 traqueurs Croc-moqueur des environs pour pouvoir quitter l'arbre sans danger.",
    ["Reward from the quest 'Final Passage', the last of ten steps."] = "Récompense de la quête « Final Passage », la dernière de dix étapes.",
    ["Bring Beginnings of the Undead Threat out of Scarlet Monastery Library."] = "Rapportez Les débuts de la menace morte-vivante de la bibliothèque du Monastère écarlate.",
    ["Pick the hammer over the other reward."] = "Choisissez le marteau plutôt que l'autre récompense.",
    ["Pick the wand over the other reward."] = "Choisissez la baguette plutôt que l'autre récompense.",
    ["This quest is offered after you turn in 10 library books to Garion Wendell in Stormwind or Owen Thadd in Undercity."] = "Cette quête est proposée après avoir rendu 10 livres de bibliothèque à Garion Wendell à Hurlevent ou à Owen Thadd à Fossoyeuse.",
    ["Here's your armor, &lt;name&gt;. &nbsp;This will stand up to the strongest assaults or my name isn't Furen Longbeard!And I have to thank you. &nbsp;I learned a lot while working with the materials you brought me. &nbsp;I think I'll have another breakthrough one day!I'm going to send what I learned to other blacksmiths of the Alliance.I'll tell them you were a big help, and maybe they'll want to return the favor."] = "Voici votre armure, <name>. Elle résistera aux pires assauts, ou je ne m'appelle pas Furen Longuebarbe ! Et je dois vous remercier. J'ai beaucoup appris en travaillant les matériaux que vous m'avez apportés. Je crois que je ferai une autre découverte un de ces jours ! Je vais transmettre ce que j'ai appris aux autres forgerons de l'Alliance. Je leur dirai que vous m'avez beaucoup aidé, et peut-être qu'ils voudront vous rendre la pareille.",
    ["This quest is offered after you turn in 20 library books to Garion Wendell in Stormwind or Owen Thadd in Undercity."] = "Cette quête est proposée après avoir rendu 20 livres de bibliothèque à Garion Wendell à Hurlevent ou à Owen Thadd à Fossoyeuse.",
    ["Here are some weapons, hot off the anvil and made with the new umbral ore you brought me!Please, &lt;name&gt;, take your pick!"] = "Voici quelques armes, tout juste sorties de l'enclume et forgées avec le nouveau minerai ombral que vous m'avez apporté ! Je vous en prie, <name>, faites votre choix !",
    ["A level 10 Quest."] = "Une quête de niveau 10.",
    ["I can barely believe it! &nbsp;Furen's technique was a success, and this armor should withstand tremendous levels of stress.Here you are, &lt;name&gt;. &nbsp;And thank you. &nbsp;I wouldn't have believed Furen's discovery if you hadn't gathered the materials I needed to test it myself."] = "J'ai du mal à y croire ! La technique de Furen a fonctionné, et cette armure devrait supporter des contraintes énormes. Tenez, <name>. Et merci. Je n'aurais jamais cru à la découverte de Furen si vous n'aviez pas rassemblé les matériaux pour que je la teste moi-même.",
    ["I will keep three of the weapons you returned to me, as mementos of my pain and loss. &nbsp;But please, &lt;name&gt;, choose your favorite of the heirlooms and keep it for yourself.May it serve you greater than it served its cursed, former owners."] = "Je garderai trois des armes que vous m'avez rapportées, en souvenir de ma douleur et de ma perte. Mais je vous en prie, <name>, choisissez votre préférée parmi ces reliques de famille et gardez-la. Puisse-t-elle mieux vous servir qu'elle n'a servi ses anciens propriétaires maudits.",
    ["As a hero of the Stormpike, you may choose one item from these recently plun... er, recovered treasures."] = "En tant que héros des Foudrepiques, vous pouvez choisir un objet parmi ces trésors récemment pill... euh, récupérés.",
    ["ProgressIt is good to see you again, &lt;class&gt;."] = "Je suis heureux de vous revoir, <class>.",
    ["I had not expected you to return."] = "Je ne pensais pas vous voir revenir.",
    ["Alas, you have proven yourself a brave and honorable soldier of the Frostwolf.Your time has come again, &lt;name&gt;."] = "Hélas, vous vous êtes montré un soldat brave et honorable des Loups-de-givre. Votre heure est de nouveau venue, <name>.",
    ["You have earned a new ranking and as such, a new insignia denoting this rise in stature.Present your insignia."] = "Vous avez gagné un nouveau grade, et donc un nouvel insigne qui marque votre ascension. Présentez votre insigne.",
    ["ProgressThe base buzzes with news of your exploits in the Field of Strife!"] = "La base bourdonne de récits de vos exploits sur le Champ de la discorde !",
    ["You have struck mighty blows against our enemy - crushing their morale!"] = "Vous avez porté des coups terribles à notre ennemi, au point de briser son moral !",
    ["For this, you have earned a rank of honor among the Stormpike.Present your insignia."] = "Pour cela, vous avez gagné un grade d'honneur chez les Foudrepiques. Présentez votre insigne.",
    ["Alliance only."] = "Alliance uniquement.",
    ["Accept this talisman, &lt;class&gt;."] = "Acceptez ce talisman, <class>.",
    ["Accept it and use its power to strike down our mutual enemies.Know that around your neck you carry a piece of history."] = "Acceptez-le et servez-vous de son pouvoir pour abattre nos ennemis communs. Sachez que vous portez au cou un morceau d'histoire.",
    ["Kezan was once a grand territory of the Zandalar Empire."] = "Kezan fut autrefois un grand territoire de l'empire Zandalar.",
    ["Alas, the taint of goblin trade princes would force out my proud brothers and sisters.Kezan is now home to the goblin capital of the Undermine; but know that before the taint, it held greatness."] = "Hélas, la souillure des princes marchands gobelins a chassé mes fiers frères et sœurs. Kezan abrite aujourd'hui la capitale gobeline de Terremine, mais sachez qu'avant la souillure, elle connut la grandeur.",
    ["Still to this day Kezan is considered sacred land to my people."] = "Aujourd'hui encore, Kezan est une terre sacrée pour mon peuple.",
    ["ProgressCall forth your demons, &lt;class&gt;."] = "Appelez vos démons, <class>.",
    ["Let them bask in the energy of Kezan's Taint."] = "Qu'ils se gorgent de l'énergie de la Souillure de Kezan.",
    ["Command them on the field of battle!"] = "Menez-les sur le champ de bataille !",
    ["Decimate the enemy!Yes..."] = "Décimez l'ennemi ! Oui...",
    ["The time has come to apply the final enhancement to Kezan's Taint."] = "Le moment est venu d'apporter la dernière amélioration à la Souillure de Kezan.",
    ["Give me the talisman."] = "Donnez-moi le talisman.",
    ["Here's your armor, &lt;name&gt;. &nbsp;Furen's process worked brilliantly! &nbsp;Perfectly! &nbsp;Marvelously, truly!You could run this armor over with a siege engine and it would spring right back into shape!"] = "Voici votre armure, <name>. Le procédé de Furen a fonctionné à merveille ! Parfaitement ! Merveilleusement, vraiment ! On pourrait rouler sur cette armure avec un engin de siège, elle reprendrait aussitôt sa forme !",
    ["ProgressBefore me stands an exalted hero of the Alliance.&lt;Lieutenant Haggerdin salutes.&gt;Few have earned such a rank among the Stormpike."] = "Devant moi se tient un héros exalté de l'Alliance. <Le lieutenant Haggerdin salue.> Rares sont ceux qui ont gagné un tel grade chez les Foudrepiques.",
    ["I have watched the enemy fall before you."] = "J'ai vu l'ennemi tomber devant vous.",
    ["I have seen their resolve crumble in your presence."] = "J'ai vu sa détermination s'effondrer en votre présence.",
    ["When you enter the fray, you become the beacon of hope for our forces!Present your insignia."] = "Quand vous entrez dans la mêlée, vous devenez le phare de l'espoir pour nos forces ! Présentez votre insigne.",
    ["ProgressAn extremely sturdy cabinet stands before you, securely fastened shut by a built-in lock. &nbsp;The front of the cabinet is deeply scratched and marked. &nbsp;This could be surmised as being from numerous and violent failed attempts to reveal whatever secrets the cabinet currently obfuscates from view.If you are going to open this cabinet, you will need to find the key."] = "Un cabinet extrêmement robuste se dresse devant vous, solidement fermé par une serrure intégrée. Sa façade est profondément rayée et marquée, sans doute par de nombreuses tentatives violentes et vaines de percer les secrets qu'il cache. Pour ouvrir ce cabinet, il vous faudra trouver la clé.",
    ["ProgressMolthor delivers word from King Rastakhan, &lt;name&gt;."] = "Molthor apporte un message du roi Rastakhan, <name>.",
    ["The royal court is most impressed with your decimation of the Hakkari forces."] = "La cour royale est très impressionnée par la façon dont vous avez décimé les forces hakkari.",
    ["I am to award you with the final weave in your talisman."] = "Je dois vous remettre le dernier tissage de votre talisman.",
    ["Hand it to me."] = "Donnez-le-moi.",
    ["Rituals of Power sends you into Scarlet Monastery Library."] = "« Rituals of Power » vous envoie dans la bibliothèque du Monastère écarlate.",
    ["Bring Bink her Mage-tastic Gizmonitor."] = "Apportez à Bink son Gizmonitor Mage-tastique.",
    ["Here is your robe. &nbsp;It's one of my best made yet! &nbsp;Wear it with pride, and when people ask... tell them you got it at the Larson Clothiers!"] = "Voici votre robe. C'est une des plus réussies que j'aie jamais faites ! Portez-la avec fierté, et si on vous demande... dites que vous l'avez eue chez Larson Couturiers !",
    ["I have finished with your piece of armor, and I am quite pleased. &nbsp;Furen's new techniques meshed perfectly with my own and I am sure this armor will prove to be quite resilient.Thank you, &lt;name&gt;. &nbsp;And may this serve you well in future battles."] = "J'ai terminé votre pièce d'armure, et j'en suis très content. Les nouvelles techniques de Furen se sont parfaitement mariées aux miennes, et je suis sûr que cette armure sera très résistante. Merci, <name>. Puisse-t-elle vous servir dans vos combats à venir.",
    ["&lt;name&gt;, your successful re-engineering of the cauldrons is a tremendous victory for us!Let all within my presence hear: for service to the Forsaken and to the Horde as a whole above and beyond what was expected - in the face of overwhelming odds and incredible danger, might I add - I give &lt;name&gt; this, and I extend upon him our undying gratitude as a true hero of the Horde. &nbsp;Huzzah!"] = "<name>, votre réingénierie réussie des chaudrons est une immense victoire pour nous ! Que tous ceux qui m'entendent le sachent : pour des services rendus aux Réprouvés et à toute la Horde bien au-delà de ce qu'on attendait, face à des forces écrasantes et un danger inouï, j'ajouterai, je remets ceci à <name>, et je lui exprime notre gratitude éternelle en véritable héros de la Horde. Hourra !",
    ["Here is your nether-lace, &lt;name&gt;. &nbsp;It is both comfortable and durable, and holds the magic of the laughing sisters' hair.Enjoy, and if you find it amenable, please mention so to Deino. &nbsp;She is a &lt;class&gt; on whose good side I wish to stay..."] = "Voici votre dentelle de néant, <name>. Elle est à la fois confortable et solide, et garde la magie des cheveux des sœurs rieuses. Profitez-en, et si elle vous plaît, dites-le donc à Deino. C'est une <class> dont je tiens à rester dans les bonnes grâces...",
    ["Now isn't this interesting?"] = "Voilà qui est intéressant, non ?",
    ["You say you found this tablet on a small, deserted island at The Overlook Cliffs in The Hinterlands, &lt;class&gt;?"] = "Vous dites avoir trouvé cette tablette sur un petit îlot désert près des falaises du Surplomb, dans les Hinterlands, <class> ?",
    ["Very interesting indeed."] = "Très intéressant, vraiment.",
    ["I thank you for your efforts in this matter."] = "Je vous remercie de vos efforts dans cette affaire.",
    ["Our Dark Lady shall be very pleased with this discovery."] = "Notre Dame noire sera ravie de cette découverte.",
    ["Here, allow me to reward you proportionately."] = "Tenez, permettez-moi de vous récompenser à la hauteur.",
    ["Erlgadin in Stranglethorn Vale."] = "Erlgadin, dans la vallée de Strangleronce.",
    ["Progress*Whir* *Click* &nbsp;I seek rare fish for Fishmaster Bluegill to catalogue. &nbsp; If you bring me a Keefer's Angelfish, I will provide you with this fine reward. *Zzzap* *Whir*."] = "*Vrrr* *Clic* Je cherche des poissons rares pour que le maître pêcheur Bleubranchie les répertorie. Si vous m'apportez un Poisson-ange de Keefer, je vous donnerai cette belle récompense. *Bzzzt* *Vrrr*.",
    ["Find what awaits you."] = "Découvrez ce qui vous attend.",
    ["It will take time for our scholars to study the pendant you brought us. &nbsp;But for your service to the Horde I would like to offer you a small token.Thank you, &lt;name&gt;. &nbsp;Your acts bring honor to you, and to us."] = "Il faudra du temps à nos érudits pour étudier le pendentif que vous nous avez apporté. Mais pour vos services rendus à la Horde, j'aimerais vous offrir un petit présent. Merci, <name>. Vos actes vous honorent, et nous honorent aussi.",
    ["Return the monogrammed silver hair clip to its owner."] = "Rendez la barrette en argent monogrammée à sa propriétaire.",
    ["Here are your robes, &lt;name&gt;. &nbsp;Wear them well."] = "Voici vos robes, <name>. Portez-les bien.",
    ["ProgressIt is good to see you in good health, &lt;name&gt;."] = "Je suis heureux de vous voir en bonne santé, <name>.",
    ["The glorious battles you have undertaken affect all life on this planet."] = "Les glorieuses batailles que vous avez menées touchent toute vie sur ce monde.",
    ["Hakkar must never leave the confines of Zul'Gurub as the world will surely collapse beneath his immense hunger.Give me your talisman and I shall amplify its strength."] = "Hakkar ne doit jamais quitter Zul'Gurub, car le monde s'effondrerait sous son immense faim. Donnez-moi votre talisman et j'en amplifierai la force.",
    ["Use the Strength of Mugamba to punish our enemies!"] = "Servez-vous de la Force de Mugamba pour punir nos ennemis !",
    ["ProgressDrek'Thar sings your praises."] = "Drek'Thar chante vos louanges.",
    ["Kalimdor is abuzz with tales of your heroics."] = "Kalimdor bruisse des récits de vos exploits.",
    ["The Warchief glows - your stalwart defense of our clan has pleased him greatly.You have earned the Eye of Command.Present your insignia, Commander &lt;name&gt;."] = "Le chef de guerre rayonne : votre défense acharnée de notre clan l'a beaucoup réjoui. Vous avez gagné l'Œil de commandement. Présentez votre insigne, commandant <name>.",
    ["ProgressTales of your battles against the Gurubashi are whispered in the winds, &lt;class&gt;."] = "Les récits de vos combats contre les Gurubashi se murmurent dans les vents, <class>.",
    ["Even royalty is beginning to talk of your deeds."] = "Même la royauté commence à parler de vos exploits.",
    ["It is rumored that King Rastakhan even mentioned you by name.The time has come to imbue the Eye."] = "On dit que le roi Rastakhan a même cité votre nom. Le moment est venu d'imprégner l'Œil.",
    ["Hand me the talisman and I shall perform the service."] = "Donnez-moi le talisman et j'accomplirai le rituel.",
    ["ProgressNever have I seen such tenacity!"] = "Jamais je n'ai vu une telle ténacité !",
    ["The Bronze Flight grants you one final enchantment."] = "Le Vol de bronze vous accorde un dernier enchantement.",
    ["The Timeless One himself has requested it so!Hand me your signet ring so that I may make the necessary adjustments."] = "L'Intemporel lui-même l'a demandé ! Donnez-moi votre chevalière, que je fasse les ajustements nécessaires.",
    ["Know this, heathen: A catastrophe has brought us together."] = "Sache ceci, païen : une catastrophe nous a réunis.",
    ["Your pagan ways are neither understood nor appreciated by Zandalar but we are a fair people."] = "Tes pratiques païennes ne sont ni comprises ni appréciées des Zandalar, mais nous sommes un peuple juste.",
    ["Wear this brand around your neck."] = "Porte cette marque autour du cou.",
    ["It shall serve as both a warning to our enemies and a symbol of your friendship to Zandalar.Continue to serve our people and I will amplify the power of the brand."] = "Elle servira à la fois d'avertissement à nos ennemis et de symbole de ton amitié envers les Zandalar. Continue de servir notre peuple et j'amplifierai le pouvoir de la marque.",
    ["&lt;name&gt;, you have slain all three beasts that comprise the Ashenvale Hunt. &nbsp;You have brought me adequate proof of their demise; there is no question of your strength and tenacity. &nbsp;The blood of a hunter streaks through your veins, and you should be commended!Please, accept this bauble as a sign of congratulations on your mighty deeds done in Ashenvale for the Horde today. &nbsp;May your ancestors watch over you!"] = "<name>, vous avez tué les trois bêtes de la Chasse d'Ashenvale. Vous m'avez apporté des preuves suffisantes de leur mort ; votre force et votre ténacité ne font aucun doute. Le sang d'un chasseur coule dans vos veines, et vous méritez des éloges ! Je vous en prie, acceptez cette babiole en signe de félicitations pour les hauts faits accomplis aujourd'hui en Ashenvale pour la Horde. Que vos ancêtres veillent sur vous !",
    ["ProgressAh, &lt;name&gt;, it is good to smell you again.You'll have to excuse my sense of humor."] = "Ah, <name>, quel plaisir de vous sentir à nouveau. Excusez mon humour.",
    ["It can be most foul at times.I sense that you have caused great anguish to our enemies."] = "Il peut être fort nauséabond par moments. Je sens que vous avez causé une grande angoisse à nos ennemis.",
    ["The forces of Hakkar cry out your name in anger."] = "Les forces d'Hakkar hurlent votre nom de colère.",
    ["This is most excellent.You have earned another weave on your talisman."] = "C'est excellent. Vous avez gagné un nouveau tissage pour votre talisman.",
    ["ProgressKing Rastakhan sends his regards, Master &lt;name&gt;."] = "Le roi Rastakhan vous salue, maître <name>.",
    ["Such an honor has never been given to one outside the Zandalar tribe.Give me your talisman so that I may enhance it once more."] = "Un tel honneur n'a jamais été accordé à quelqu'un d'extérieur à la tribu Zandalar. Donnez-moi votre talisman, que je l'améliore encore une fois.",
    ["Know that the Rage of Mugamba is now intrinsically connected to your very soul."] = "Sachez que la Rage de Mugamba est désormais liée à votre âme même.",
    ["Greetings, champion."] = "Salutations, champion.",
    ["I am Jonathan, keeper of the sacred gong and eternal watcher of the Bronze Flight.I have been empowered by the Timeless One himself to grant you an item of your choosing from his timeless treasure trove."] = "Je suis Jonathan, gardien du gong sacré et veilleur éternel du Vol de bronze. L'Intemporel lui-même m'a donné le pouvoir de vous accorder l'objet de votre choix parmi son trésor hors du temps.",
    ["May it aid you in your battles against C'Thun."] = "Puisse-t-il vous aider dans vos combats contre C'Thun.",
    ["Help Walton survive the encounter with Terry Longdrink and the Kul Tiras marines."] = "Aidez Walton à survivre à la rencontre avec Terry Longdrink et les marines de Kul Tiras.",
    ["Deathstalker Masoj needs you to place the three Apothecary Vials on peaks around Hillsbrad Foothills and return to him."] = "La Nécrotraqueuse Masoj a besoin que vous placiez les trois fioles d'apothicaire sur des sommets des contreforts de Hautebrande, puis que vous reveniez la voir.",
    ["ProgressSha-mon!"] = "Sha-mon !",
    ["Maywiki make a joke!&lt;Maywiki laughs.&gt;So, you been using the spirits and elements against our enemies in Zul'Gurub, eh?"] = "Maywiki fait une blague ! <Maywiki rit.> Alors, tu t'es servi des esprits et des éléments contre nos ennemis de Zul'Gurub, hein ?",
    ["Spirits be praised!Maywiki gonna brighten your orb."] = "Louange aux esprits ! Maywiki va faire briller ton orbe.",
    ["Give it here, &lt;name&gt;."] = "Donne-le ici, <name>.",
    ["Slay Arnak Grimtotem and bring proof of your deed to Cliffwatcher Longhorn in Freewind Post."] = "Tuez Arnak Totem-sinistre et rapportez la preuve de votre exploit au guetteur de la falaise Longuecorne, au poste de Librevent.",
    ["Reward from the quest 'Wanted!"] = "Récompense de la quête « Wanted!",
    ["Marez Cowl'."] = "Marez Cowl ».",
    ["Otto and Falconcrest'."] = "Otto and Falconcrest ».",
    ["&lt;name&gt;, I have crafted these weapons with the elunite you brought to me. &nbsp;Please, take whichever most suits you.And I must thank you. &nbsp;Working with elunite is both an honor and a pleasure."] = "<name>, j'ai forgé ces armes avec l'élunite que vous m'avez apportée. Je vous en prie, prenez celle qui vous convient le mieux. Et je dois vous remercier : travailler l'élunite est à la fois un honneur et un plaisir.",
    ["I have the whirlwind heart, and am ready to place it within your vessel of choice.Choose your weapon, &lt;name&gt;, and know that its power is the power of Cyclonian."] = "J'ai le cœur de tourbillon, prêt à être placé dans le réceptacle de votre choix. Choisissez votre arme, <name>, et sachez que sa puissance est celle de Cyclonian.",
    ["ProgressIt yearns to grow, &lt;name&gt;."] = "Il aspire à grandir, <name>.",
    ["The talisman has soaked in all that you have done."] = "Le talisman s'est imprégné de tout ce que vous avez accompli.",
    ["The thousands of troll corpses littering Zul'Gurub have fueled its power."] = "Les milliers de cadavres de trolls qui jonchent Zul'Gurub ont nourri son pouvoir.",
    ["Hand it to me and I shall make the final enhancement."] = "Donnez-le-moi et j'apporterai la dernière amélioration.",
    ["ProgressImpressive, &lt;name&gt;."] = "Impressionnant, <name>.",
    ["You have a gift for killing that I have not sensed in another in many years."] = "Vous avez un don pour tuer que je n'avais pas senti chez quelqu'un depuis bien des années.",
    ["Even Molthor is aware of the work that you have done for Zandalar."] = "Même Molthor a entendu parler du travail que vous avez accompli pour les Zandalar.",
    ["It is time to enhance your talisman further."] = "Il est temps d'améliorer encore votre talisman.",
    ["Give it to me."] = "Donnez-le-moi.",
    ["A Gnomeregan oddity whose Use effect grants a huge burst of attack speed."] = "Une curiosité de Gnomeregan dont l'effet Utiliser donne une énorme poussée de vitesse d'attaque.",
    ["Feral druids kept it for that alone, because it works in cat form -- and it has limited charges, so every use is a decision."] = "Les druides farouches le gardaient rien que pour ça, car il fonctionne en forme de félin, et ses charges sont limitées : chaque utilisation est un choix.",
    ["A Nightmare-corrupted green dragon who splits himself into shades rather than face a fight whole."] = "Un dragon vert corrompu par le Cauchemar, qui se divise en ombres plutôt que d'affronter le combat d'un seul bloc.",
    ["A blue dragon slain in Northrend and raised as a frost wyrm."] = "Un dragon bleu tué en Norfendre et relevé en wyrm de givre.",
    ["He guards the final approach to Kel'Thuzad's chamber."] = "Il garde l'ultime approche de la chambre de Kel'Thuzad.",
    ["A bounty has been placed on the head of Marez Cowl, a high-level advisor and operative of the Syndicate."] = "Une prime a été offerte pour la tête de Marez Cowl, conseillère de haut rang et agent du Syndicat.",
    ["She was last seen within the Syndicate controlled territory of Stromgarde."] = "Elle a été vue pour la dernière fois sur le territoire de Stromgarde, contrôlé par le Syndicat.",
    ["A core hound of the deep fire, kept as a guard beast and fed by Ragnaros's lieutenants."] = "Un chien du magma des feux profonds, gardé comme bête de garde et nourri par les lieutenants de Ragnaros.",
    ["A crafted helm that outlived several tiers of raid gear."] = "Un heaume fabriqué qui a survécu à plusieurs paliers d'équipement de raid.",
    ["Its plans were the thing guilds actually fought over."] = "Ce sont ses plans que les guildes se disputaient vraiment.",
    ["A crypt lord of Azjol-Nerub who took Arthas's side."] = "Un seigneur des cryptes d'Azjol-Nérub qui s'est rangé du côté d'Arthas.",
    ["He holds the Arachnid Quarter's outermost hall."] = "Il tient la salle la plus extérieure du quartier des Arachnides.",
    ["A death knight who trains the Scourge's new officers."] = "Un chevalier de la mort qui forme les nouveaux officiers du Fléau.",
    ["He is too strong for his own students to touch, which is exactly the point of the lesson."] = "Il est trop fort pour que ses propres élèves le touchent, et c'est justement le but de la leçon.",
    ["A fungal horror grown in the Plague Quarter's spore vats -- less a creature than a crop that got out of hand."] = "Une horreur fongique cultivée dans les cuves à spores du quartier de la Peste, moins une créature qu'une récolte qui a mal tourné.",
    ["A giant spider webbed into the depths of the Arachnid Quarter, fed on whatever the Scourge no longer needs."] = "Une araignée géante tapie dans les profondeurs du quartier des Arachnides, nourrie de tout ce dont le Fléau n'a plus besoin.",
    ["A green dragon of Ysera's flight, turned by the Nightmare and hunted across Feralas ever since."] = "Un dragon vert du vol d'Ysera, retourné par le Cauchemar et traqué à travers Féralas depuis.",
    ["A hound handler of Ragnaros's court, who curses healing shut before the fighting starts."] = "Un maître-chien de la cour de Ragnaros, qui maudit les soins avant même que le combat commence.",
    ["A human lord who traded his life for undeath and became a lich in Scholomance."] = "Un seigneur humain qui a troqué sa vie contre la non-mort et est devenu une liche à Scholomance.",
    ["Killing him takes a blade specifically made to sever the bargain."] = "Pour le tuer, il faut une lame forgée exprès pour rompre ce pacte.",
    ["A lieutenant of Ragnaros who fights surrounded by his Firesworn, and grows stronger each time one of them falls."] = "Un lieutenant de Ragnaros qui combat entouré de ses Lige du feu, et devient plus fort chaque fois que l'un d'eux tombe.",
    ["A living mass of qiraji poison."] = "Une masse vivante de poison qiraji.",
    ["It has to be frozen solid and then shattered, which is not how most things die."] = "Il faut la geler entièrement puis la briser, ce qui n'est pas la façon dont meurent la plupart des choses.",
    ["A necromancer of the Plague Quarter, promoted for his skill at raising what he had just finished killing."] = "Un nécromancien du quartier de la Peste, promu pour son talent à relever ce qu'il venait de tuer.",
    ["A pit lord left behind when the Legion's invasion collapsed, still holding the Tainted Scar where the Dark Portal's blast burned the land."] = "Un seigneur des abîmes resté sur place quand l'invasion de la Légion s'est effondrée, qui tient toujours la Balafre impure, là où l'explosion de la Porte des ténèbres a brûlé la terre.",
    ["A plain plate glove that became famous for its random enchants -- the of Strength roll is a 7.9% chance and was worth chasing over guaranteed epics for years."] = "Un simple gant de plaques devenu célèbre pour ses enchantements aléatoires : le tirage « de Force » a 7,9 % de chances et valait d'être poursuivi plutôt que des épiques garantis pendant des années.",
    ["A princess of the earth elementals and the reason Maraudon is poisoned -- she holds the body of Zaetar, her demigod consort, at its heart."] = "Une princesse des élémentaires de terre, et la raison pour laquelle Maraudon est empoisonnée : elle garde en son cœur le corps de Zaetar, son consort demi-dieu.",
    ["A qiraji brood matron whose poison is potent enough that the fight is really a race against her venom."] = "Une matriarche de couvée qiraji dont le poison est si puissant que le combat est en réalité une course contre son venin.",
    ["A red dragon of Alexstrasza's flight, broken by Nefarian's experiments."] = "Un dragon rouge du vol d'Alexstrasza, brisé par les expériences de Nefarian.",
    ["He asks to be killed before the corruption finishes taking him, and apologises while he fights."] = "Il demande qu'on le tue avant que la corruption ne l'emporte, et s'excuse en combattant.",
    ["A sandworm grown enormous under the desert, surfacing only to feed."] = "Un ver des sables devenu énorme sous le désert, qui ne remonte à la surface que pour se nourrir.",
    ["A stitched hound kept half-starved on purpose, so it would eat anything the Construct Quarter sent its way."] = "Un chien recousu volontairement affamé, pour qu'il mange tout ce que le quartier des Assemblages lui envoie.",
    ["A stone giant pressed into qiraji service, who drains the mana of everyone fighting him and turns to rock when full."] = "Un géant de pierre au service des qiraji, qui draine le mana de tous ceux qui le combattent et se change en roche une fois plein.",
    ["A vast qiraji burrower that spawns its young mid-fight and hurls intruders into the walls."] = "Un immense fouisseur qiraji qui engendre ses petits en plein combat et projette les intrus contre les murs.",
    ["A worshipper of Kel'Thuzad who brought her followers with her into undeath, and still commands them."] = "Une adoratrice de Kel'Thuzad qui a entraîné ses fidèles avec elle dans la non-mort, et les commande toujours.",
    ["An Old God, buried under Ahn'Qiraj by the titans rather than killed."] = "Un Dieu très ancien, enterré sous Ahn'Qiraj par les titans plutôt que tué.",
    ["It has been whispering to the qiraji ever since, and the whole war exists because it never stopped."] = "Il murmure aux qiraji depuis lors, et toute cette guerre existe parce qu'il ne s'est jamais tu.",
    ["An abomination stitched together from the Scourge's leftovers, built for nothing but raw strength."] = "Une abomination assemblée à partir des restes du Fléau, conçue uniquement pour la force brute.",
    ["Archmage Arugal called the worgen to Silverpine to defend against the Scourge, lost control of them immediately, and went mad in Shadowfang Keep among the things he had summoned."] = "L'archimage Arugal a appelé les worgens à Silverpine pour se défendre contre le Fléau, en a perdu le contrôle aussitôt, et a sombré dans la folie au donjon d'Ombrecroc au milieu de ce qu'il avait invoqué.",
    ["Arugal's own belt."] = "La ceinture d'Arugal lui-même.",
    ["He summoned the worgen to save Silverpine, then lost his mind in Shadowfang Keep surrounded by what he had called."] = "Il a invoqué les worgens pour sauver Silverpine, puis a perdu la raison au donjon d'Ombrecroc, entouré de ce qu'il avait appelé.",
    ["Avast Lubber!"] = "Par tous les diables, moussaillon !",
    ["Bring me 12 trinkets of the Arena Master and then ye shall be a Grandmaster of the Gurubashi Arena!"] = "Apporte-moi 12 babioles du maître de l'arène et tu seras grand maître de l'arène des Gurubashi !",
    ["C'Thun's mouthpiece."] = "La voix de C'Thun.",
    ["Everything the qiraji believe, they believe because he told them the Old God said it."] = "Tout ce que croient les qiraji, ils le croient parce qu'il leur a dit que le Dieu très ancien l'avait dit.",
    ["Cut from the fang of one of Nefarian's drakes."] = "Taillé dans le croc d'un des drakes de Nefarian.",
    ["Tanks wore it for the stun it shrugs off, not the numbers on it."] = "Les tanks le portaient pour l'étourdissement qu'il annule, pas pour ses chiffres.",
    ["Deathwing's son, working under Blackrock Mountain to breed the chromatic flight -- dragons carrying the blood of all five."] = "Le fils d'Aile-de-mort, qui travaille sous le mont Rochenoire à élever le vol chromatique : des dragons portant le sang des cinq vols.",
    ["He spent years in Stormwind's court as Lord Victor Nefarius while the work went on."] = "Il a passé des années à la cour de Hurlevent sous le nom de lord Victor Nefarius pendant que le travail se poursuivait.",
    ["Ghamoo-ra is the ancient turtle the naga keep in Blackfathom Deeps -- old enough that the Twilight cultists there treat it as part of the temple."] = "Ghamoo-ra est l'antique tortue que les nagas gardent à Brassenoire, si vieille que les cultistes du Crépuscule la considèrent comme une partie du temple.",
    ["Hakkar's chief hexxer, who fights by binding pieces of his enemies' spirits and setting them loose."] = "Le principal maléficier d'Hakkar, qui combat en liant des fragments de l'esprit de ses ennemis avant de les relâcher.",
    ["He has overpowered all attempts at his capture."] = "Il a déjoué toutes les tentatives de capture.",
    ["The Stormwind Army has placed a generous bounty on the Gnoll."] = "L'armée de Hurlevent offre une généreuse prime pour ce gnoll.",
    ["I had not expected you to return."] = "Je ne pensais pas vous voir revenir.",
    ["Alas, you have proven yourself a brave and honorable soldier of the Frostwolf."] = "Hélas, vous vous êtes montré un soldat brave et honorable des Loups-de-givre.",
    ["Keeper of Naxxramas's plague works, and of the corridor of eruptions that has killed more raiders than he has."] = "Gardien des ateliers de la peste de Naxxramas, et du couloir des éruptions qui a tué plus de raideurs que lui.",
    ["Nefarian's best result: a two-headed chromatic horror carrying the breath of every dragonflight at once."] = "La plus belle réussite de Nefarian : une horreur chromatique à deux têtes portant à la fois le souffle de chaque vol draconique.",
    ["Once an archmage of the Kirin Tor, he left Dalaran to found the Cult of the Damned and served Ner'zhul willingly."] = "Ancien archimage du Kirin Tor, il a quitté Dalaran pour fonder le culte des Damnés et a servi Ner'zhul de son plein gré.",
    ["Killed at Andorhal and raised as a lich, he rules Naxxramas from a phylactery at its heart."] = "Tué à Andorhal et relevé en liche, il règne sur Naxxramas depuis un phylactère placé en son cœur.",
    ["One of Hakkar's high priests, who returns to his feet twice before he stays down."] = "Un des grands prêtres d'Hakkar, qui se relève deux fois avant de rester à terre.",
    ["One of Nefarian's three guardian drakes, holding the suspended walkways above the lair floor."] = "Un des trois drakes gardiens de Nefarian, qui tient les passerelles suspendues au-dessus du repaire.",
    ["One of Ysera's four green consorts, corrupted by the Emerald Nightmare and now roaming Feralas, rotting the ground it stands on."] = "Un des quatre consorts verts d'Ysera, corrompu par le Cauchemar d'émeraude et qui erre désormais à Féralas, pourrissant le sol sous ses pas.",
    ["One of the three qiraji councillors who fight as one -- kill any of them and the survivors grow stronger."] = "Un des trois conseillers qiraji qui combattent comme un seul : tuez l'un d'eux et les survivants deviennent plus forts.",
    ["One of three drakes guarding Nefarian's inner lair, and the one that heals itself off the wounds it deals."] = "Un des trois drakes qui gardent le repaire intérieur de Nefarian, celui qui se soigne grâce aux blessures qu'il inflige.",
    ["One of three weapons from the same solitary warrior trial."] = "Une des trois armes issues de la même épreuve solitaire de guerrier.",
    ["Choosing it means giving up the axe and the staff for good."] = "La choisir, c'est renoncer pour de bon à la hache et au bâton.",
    ["Ragnaros wielded this hammer as the Firelord."] = "Ragnaros maniait ce marteau en tant que seigneur du Feu.",
    ["Reforging it means taking the Eye of Sulfuras from Ragnaros himself and setting it into the Sulfuron Hammer."] = "Pour le reforger, il faut prendre l'Œil de Sulfuras à Ragnaros lui-même et le sertir dans le Marteau de Sulfuron.",
    ["Razuvious's colleague in the Military Quarter, who fights from behind his own dead and keeps sending them forward."] = "Le collègue de Razuvious au quartier Militaire, qui combat derrière ses propres morts et ne cesse de les envoyer en avant.",
    ["Revelosh was a Shadowforge explorer who went into Uldaman looking for the origin of the dwarves, and became part of the ruin instead."] = "Revelosh était un explorateur Ombreforge entré dans Uldaman à la recherche de l'origine des nains, et qui est devenu une part de la ruine.",
    ["Rise and be honored!"] = "Relevez-vous et soyez honoré !",
    ["Present your insignia."] = "Présentez votre insigne.",
    ["Serra'kis is the great water beast the naga breed in the flooded halls of Blackfathom Deeps, and the reason the lower temple is under water at all."] = "Serra'kis est la grande bête aquatique que les nagas élèvent dans les salles inondées de Brassenoire, et la raison pour laquelle le temple inférieur est sous l'eau.",
    ["Son of Blackhand and the last warchief of the Dark Horde, still holding Blackrock Spire long after the rest of the Horde moved on."] = "Fils de Main-noire et dernier chef de guerre de la Horde noire, qui tient toujours le pic de Rochenoire bien après le départ du reste de la Horde.",
    ["Teebu's blade sets things on fire for reasons no one has ever explained."] = "La lame de Teebu met le feu aux choses pour des raisons que personne n'a jamais expliquées.",
    ["It is famous for being almost useless and deeply desirable at the same time."] = "Elle est célèbre pour être à la fois presque inutile et terriblement désirable.",
    ["The Druids of the Fang broke from Cenarius and let the Emerald Nightmare into the Wailing Caverns."] = "Les druides du Croc ont rompu avec Cénarius et laissé le Cauchemar d'émeraude entrer dans les Cavernes des lamentations.",
    ["These were theirs."] = "Ces pièces étaient les leurs.",
    ["The Firelord, one of the four Elemental Lords, bound to the Elemental Plane until the Dark Iron dwarves summoned him under Blackrock Mountain."] = "Le seigneur du Feu, un des quatre seigneurs élémentaires, lié au plan élémentaire jusqu'à ce que les nains Sombrefer l'invoquent sous le mont Rochenoire.",
    ["The summoning cracked the mountain open and made the Molten Core."] = "L'invocation a fendu la montagne et créé le Cœur du Magma.",
    ["The Guardian's staff, broken and scattered."] = "Le bâton du Gardien, brisé et dispersé.",
    ["Rebuilding it means gathering forty splinters from Naxxramas, the base from Kel'Thuzad, and carrying it to the ruin of Karazhan where Medivh once held it."] = "Pour le reconstituer, il faut réunir quarante éclats à Naxxramas, la base sur Kel'Thuzad, et l'apporter aux ruines de Karazhan où Medivh le tenait jadis.",
    ["The Scarlet Crusade's chief scholar, who guards the Monastery library and its collection rather more aggressively than a librarian should."] = "Le principal érudit de la Croisade écarlate, qui garde la bibliothèque du Monastère et sa collection avec plus d'ardeur qu'un bibliothécaire ne devrait.",
    ["The Soulflayer, a blood god the Atal'ai priests summoned into Zul'Gurub."] = "L'Écorcheur d'âmes, un dieu du sang que les prêtres Atal'ai ont invoqué à Zul'Gurub.",
    ["He feeds on the blood of his own worshippers, which is the part they had not planned for."] = "Il se nourrit du sang de ses propres fidèles, ce qu'ils n'avaient pas prévu.",
    ["The Stromgarde Militia has placed bounties on the heads of Lord Falconcrest, and his bodyguard Otto."] = "La milice de Stromgarde a offert des primes pour la tête de lord Falconcrest et de son garde du corps Otto.",
    ["Falconcrest heads the Syndicate's efforts in the Arathi Highlands, and his death would cause a major disruption in those efforts."] = "Falconcrest dirige les efforts du Syndicat dans les hautes-terres d'Arathi, et sa mort les désorganiserait gravement.",
    ["The Whirlwind Axe comes from an elemental trial a warrior has to complete alone."] = "La Hache tourbillon vient d'une épreuve élémentaire qu'un guerrier doit accomplir seul.",
    ["Three weapons come from the same chain and you keep only one."] = "Trois armes viennent de la même suite de quêtes, et vous n'en gardez qu'une.",
    ["The black dragonflight's overseer in Lower Blackrock Spire, keeping the orcs there in line on Nefarian's behalf."] = "Le surveillant du vol noir dans les profondeurs du pic de Rochenoire, qui tient les orcs en ordre pour le compte de Nefarian.",
    ["The blade the Silver Hand carried against the Scourge, and the one Tirion Fordring's order was built around."] = "La lame que la Main d'argent portait contre le Fléau, et autour de laquelle l'ordre de Tirion Fordring s'est bâti.",
    ["Corrupted when Renault Mograine used it on his own father, Alexandros, in the Scarlet Monastery."] = "Corrompue quand Renault Mograine l'a utilisée contre son propre père, Alexandros, au Monastère écarlate.",
    ["The last of Nefarian's three drakes, and the one that simply gets angrier as the fight goes on."] = "Le dernier des trois drakes de Nefarian, celui qui devient simplement plus furieux à mesure que le combat avance.",
    ["The qiraji empire's finest soldier, who fights with her honour guard and refuses to be separated from them."] = "La meilleure guerrière de l'empire qiraji, qui combat avec sa garde d'honneur et refuse d'en être séparée.",
    ["The third of the qiraji council, who charges the moment the fight begins and does not stop."] = "Le troisième du conseil qiraji, qui charge dès le début du combat et ne s'arrête plus.",
    ["Twin emperor of the qiraji, and the one who inherited C'Thun's gift for magic instead of his brother's strength."] = "Empereur jumeau des qiraji, celui qui a hérité du don de C'Thun pour la magie plutôt que de la force de son frère.",
    ["Neither twin can be killed far from the other."] = "Aucun des jumeaux ne peut être tué loin de l'autre.",
    ["Twin emperor of the qiraji, and the stronger arm of the pair."] = "Empereur jumeau des qiraji, et le bras le plus fort du duo.",
    ["Two extra attacks on a proc, on a fast axe."] = "Deux attaques supplémentaires quand l'effet se déclenche, sur une hache rapide.",
    ["Warriors farmed Dire Maul for this one item and nothing else."] = "Les guerriers farmaient Hache-tripes rien que pour cet objet.",
    ["Wanted: Arnak Grimtotem Arnak the outcast is wanted for the heinous crimes of murder and kidnapping."] = "Avis de recherche : Arnak Totem-sinistre. Arnak le paria est recherché pour les crimes odieux de meurtre et d'enlèvement.",
    ["Handsome rewards will be given to those brave enough to bring this criminal to justice."] = "De belles récompenses attendent ceux qui auront le courage de traduire ce criminel en justice.",
    ["Wanted: Hogger A huge gnoll, Hogger, is prowling the woods in southwestern Elwynn."] = "Avis de recherche : Lardeur. Un énorme gnoll, Lardeur, rôde dans les bois du sud-ouest de la forêt d'Elwynn.",
    ["Wanted: Maggot Eye!"] = "Avis de recherche : Œil-d'asticot !",
    ["A foul beast, even by Gnoll standards, Maggot Eye has been sentenced to death for his crimes against The Forsaken."] = "Ignoble bête, même pour un gnoll, Œil-d'asticot a été condamné à mort pour ses crimes contre les Réprouvés.",
    ["This despicable villain has been stealing corpses for use by the Lich King's army."] = "Ce méprisable scélérat vole des cadavres pour l'armée du roi-liche.",
    ["We mages do more than just waggle our fingers and make pretty sparks!"] = "Nous, les mages, faisons plus que remuer les doigts et lancer de jolies étincelles !",
    ["We control magic, the base fabric of our world!"] = "Nous contrôlons la magie, l'étoffe même de notre monde !",
    ["And that takes great care, and resolve."] = "Et cela demande beaucoup de soin et de détermination.",
    ["What is left of a green dragon who went into the Sunken Temple after the Nightmare and did not come out himself."] = "Ce qui reste d'un dragon vert entré dans le temple englouti à la poursuite du Cauchemar, et qui n'en est pas ressorti lui-même.",
    ["You have earned reverence among the Guard."] = "Vous avez gagné le respect de la Garde.",
    ["Present your insignia!"] = "Présentez votre insigne !",
    ["You have earned the Eye of Command."] = "Vous avez gagné l'Œil de commandement.",
    ["Present your insignia, Commander."] = "Présentez votre insigne, commandant.",
    ["You have struck mighty blows against our enemy - crushing their morale!"] = "Vous avez porté des coups terribles à notre ennemi, au point de briser son moral !",
    ["For this, you have earned a rank of honor among the Stormpike."] = "Pour cela, vous avez gagné un grade d'honneur chez les Foudrepiques.",
    ["Your radiate command and power, shaman."] = "Vous rayonnez d'autorité et de puissance, chaman.",
    ["Exalted in the eyes of Frostwolf - the enemy cowers at the mention of your name."] = "Exalté aux yeux des Loups-de-givre : l'ennemi tremble à l'évocation de votre nom.",
    ["Your time has come again."] = "Votre heure est de nouveau venue.",
    ["You have earned a new ranking and as such, a new insignia denoting this rise in stature."] = "Vous avez gagné un nouveau grade, et donc un nouvel insigne qui marque votre ascension.",
    ["A burst of energy fills the caster, increasing his damage by 10 and armor by 150 for 15 sec."] = "Une décharge d'énergie emplit le lanceur, augmentant ses dégâts de 10 et son armure de 150 pendant 15 s.",
    ["Attack all nearby enemies, dealing weapon damage plus 5 every 3 sec for 9 sec, and reducing your own movement speed by 80%."] = "Attaque tous les ennemis proches, infligeant les dégâts de l'arme plus 5 toutes les 3 s pendant 9 s, et réduit votre vitesse de déplacement de 80 %.",
    ["Blast the target with the fires of a forge, inflicting 51 Fire damage."] = "Frappe la cible avec les feux d'une forge et lui inflige 51 points de dégâts de Feu.",
    ["Blasts enemies in front of you with the power of wind, fire, all that kind of thing!"] = "Frappe les ennemis devant vous avec la puissance du vent, du feu, et tout ce genre de choses !",
    ["Blasts nearby enemies with thunder increasing the time between their attacks by 11% for 10 sec and doing 42 Nature damage to them. � Will affect up to 4 targets."] = "Frappe les ennemis proches avec le tonnerre, ce qui augmente le temps entre leurs attaques de 11 % pendant 10 s et leur inflige 42 points de dégâts de Nature. Affecte jusqu'à 4 cibles.",
    ["Blunderflame the target for 1 to 111 Fire damage."] = "Bavure-flamme la cible pour 1 à 111 points de dégâts de Feu.",
    ["Burns the enemy for 200 damage over 30 sec."] = "Brûle l'ennemi et lui inflige 200 points de dégâts en 30 s.",
    ["Burns the target for 33 Fire damage every 3 sec for 15 sec."] = "Brûle la cible et lui inflige 33 points de dégâts de Feu toutes les 3 s pendant 15 s.",
    ["Concuss the target, slowing movement speed by 20% for 6 sec."] = "Assomme la cible, ce qui réduit sa vitesse de déplacement de 20 % pendant 6 s.",
    ["Cremate the target for 56 Fire damage."] = "Incinère la cible et lui inflige 56 points de dégâts de Feu.",
    ["Damage caused by the target is reduced by 5 for 2 min."] = "Les dégâts infligés par la cible sont réduits de 5 pendant 2 min.",
    ["Deal 294 Physical damage and stun for1.5 sec."] = "Inflige 294 points de dégâts physiques et étourdit pendant 1,5 s.",
    ["Trolls take 2 times as much damage and stun duration."] = "Les trolls subissent deux fois plus de dégâts et un étourdissement deux fois plus long.",
    ["Deal 84 Nature damage, increased by 2% per stack of Static Electricity."] = "Inflige 84 points de dégâts de Nature, augmentés de 2 % par cumul d'Électricité statique.",
    ["Deals 14 Nature damage every 3 sec to any enemy in an 8 yard radius around the caster for 12 sec."] = "Inflige 14 points de dégâts de Nature toutes les 3 s à tout ennemi dans un rayon de 8 mètres autour du lanceur pendant 12 s.",
    ["Decrease the armor of the target by 100 for 20 sec. � While affected, the target cannot stealth or turn invisible."] = "Réduit l'armure de la cible de 100 pendant 20 s. Tant qu'elle est affectée, la cible ne peut pas se camoufler ni devenir invisible.",
    ["Deals 50% increased damage to targets below 25% health."] = "Inflige 50 % de dégâts en plus aux cibles à moins de 25 % de vie.",
    ["Discipline the target, dealing 91 Physical damage."] = "Corrige la cible et lui inflige 91 points de dégâts physiques.",
    ["Canines and Hyenas are Stunned and sit for 3 sec."] = "Les canidés et les hyènes sont étourdis et s'assoient pendant 3 s.",
    ["Diseases a target for 100 Nature damage and an additional 360 damage over 1 min."] = "Inocule une maladie à la cible, qui subit 100 points de dégâts de Nature et 360 points de dégâts supplémentaires en 1 min.",
    ["Disorients the target, causing it to wander aimlessly for up to 3 sec."] = "Désoriente la cible, qui erre sans but pendant 3 s au maximum.",
    ["Dispels a magic effect on the current foe."] = "Dissipe un effet magique sur l'ennemi actuel.",
    ["Enemy is inflicted with the Bleakwood Curse that reduces their magic resistances by 25. � Can be applied up to 3 times."] = "L'ennemi est frappé par la Malédiction de Mornebois, qui réduit ses résistances magiques de 25. Cumulable jusqu'à 3 fois.",
    ["Fires a Shadow Shot at the target for 21 to 31 Shadow damage."] = "Tire une Flèche d'ombre sur la cible, qui subit 21 à 31 points de dégâts d'Ombre.",
    ["Heal yourself for 270 to 450 and increase your Strength by 120 for 30 sec."] = "Vous rend 270 à 450 points de vie et augmente votre Force de 120 pendant 30 s.",
    ["Heals the wielder for 182 damage over 14 sec."] = "Rend au porteur 182 points de vie en 14 s.",
    ["Hurl spikes at the target, dealing 45 Physical damage and jumping to 1 additional nearby enemy."] = "Lance des pointes sur la cible, qui subit 45 points de dégâts physiques, puis rebondissent sur 1 ennemi proche supplémentaire.",
    ["Each jump reduces the damage by 50%."] = "Chaque rebond réduit les dégâts de 50 %.",
    ["Ignite the target in the flames of the Great Forge, dealing 39 to 59 Holyfire damage."] = "Embrase la cible dans les flammes de la Grande forge, qui subit 39 à 59 points de dégâts de Feu sacré.",
    ["Increases your chance to Parry attacks by 2% for 9 sec."] = "Augmente vos chances de parer les attaques de 2 % pendant 9 s.",
    ["Inflict 42 Fire and 14 Frost damage, slow the target by 50% for 5 sec, reduce armor by 50, and inflict 7 Nature damage every 3 sec for 12 sec."] = "Inflige 42 points de dégâts de Feu et 14 de Givre, ralentit la cible de 50 % pendant 5 s, réduit son armure de 50 et inflige 7 points de dégâts de Nature toutes les 3 s pendant 12 s.",
    ["Knocks down all nearby enemies for 3 sec."] = "Renverse tous les ennemis proches pendant 3 s.",
    ["Launch a magic severing bolt at the target, dealing 36 Physical damage and interrupting the spell being cast for 5 sec."] = "Lance un trait magique tranchant sur la cible, qui subit 36 points de dégâts physiques, et interrompt le sort en cours pendant 5 s.",
    ["Lowers the Attack Power of the target by 40 for 1 min."] = "Réduit la puissance d'attaque de la cible de 40 pendant 1 min.",
    ["Protects the caster with a holy shield."] = "Protège le lanceur avec un bouclier sacré.",
    ["Pummel the target for 25 damage and interrupt the spell being cast for 5 sec."] = "Volée de coups sur la cible, qui subit 25 points de dégâts, et interrompt le sort en cours pendant 5 s.",
    ["Punctures target's armor, lowering it by 100."] = "Perce l'armure de la cible et la réduit de 100.",
    ["Reduce your threat to the current target making them less likely to attack you."] = "Réduit votre menace envers la cible actuelle, qui a moins de chances de vous attaquer.",
    ["Reduces an enemy's armor by 165. � Stacks up to 3 times."] = "Réduit l'armure d'un ennemi de 165. Cumulable jusqu'à 3 fois.",
    ["Reduces targets armor by 300 for 20 sec."] = "Réduit l'armure de la cible de 300 pendant 20 s.",
    ["Sear certain enchanted targets with blazing light causing them to take additional damage from Holy attacks and spells."] = "Brûle certaines cibles enchantées d'une lumière ardente, ce qui leur fait subir des dégâts supplémentaires des attaques et sorts du Sacré.",
    ["Sear the target with a vortex of blazing wind, dealing 39 to 59 Holystorm damage."] = "Brûle la cible avec un tourbillon de vent ardent, qui subit 39 à 59 points de dégâts de Tempête sacrée.",
    ["Sear your target's flesh, dealing 67 to 101 Fire damage."] = "Brûle la chair de votre cible, qui subit 67 à 101 points de dégâts de Feu.",
    ["Slice the target's ankle, slowing movement speed by 30% for 6 sec."] = "Entaille la cheville de la cible, ce qui réduit sa vitesse de déplacement de 30 % pendant 6 s.",
    ["Slices the enemy for 72 to 96 Nature damage."] = "Entaille l'ennemi, qui subit 72 à 96 points de dégâts de Nature.",
    ["Slows the target's movement by 50% for 10 sec."] = "Ralentit le déplacement de la cible de 50 % pendant 10 s.",
    ["Slows the target's movement speed by 30% and increases the time between their attacks by 25% for 5 sec."] = "Réduit la vitesse de déplacement de la cible de 30 % et augmente le temps entre ses attaques de 25 % pendant 5 s.",
    ["Smash the target for 85 damage."] = "Fracasse la cible, qui subit 85 points de dégâts.",
    ["Smite your target with the power of the holy spring, inflicting 56 Holy damage."] = "Châtie votre cible avec la puissance de la source sacrée, qui subit 56 points de dégâts du Sacré.",
    ["Smites an enemy for 30 Holy damage."] = "Châtie un ennemi, qui subit 30 points de dégâts du Sacré.",
    ["Spell damage taken by target increased by 15% for 5 sec."] = "Les dégâts des sorts subis par la cible sont augmentés de 15 % pendant 5 s.",
    ["Strike the target with a Flaming Shell for 32 to 46 Fire damage."] = "Frappe la cible avec une Coque enflammée, qui subit 32 à 46 points de dégâts de Feu.",
    ["Strike the target with a Flaming Shell, inflicting 7 Fire damage every 3 sec for 9 sec."] = "Frappe la cible avec une Coque enflammée, qui subit 7 points de dégâts de Feu toutes les 3 s pendant 9 s.",
    ["Strike your target with Keeper's Sting for 23 to 33 Nature damage."] = "Frappe votre cible avec la Piqûre du gardien, qui subit 23 à 33 points de dégâts de Nature.",
    ["Tenderize the target, increasing physical damage taken by 1 for 1 min."] = "Attendrit la cible, ce qui augmente de 1 les dégâts physiques qu'elle subit pendant 1 min.",
    ["Venom Shot the target for 23 to 33 Nature damage."] = "Tir venimeux sur la cible, qui subit 23 à 33 points de dégâts de Nature.",
    ["Naga are Stunned for 2 sec."] = "Les nagas sont étourdis pendant 2 s.",
    ["Your attacks have a high chance to poison the target for 8 Nature damage every 3 sec for 9 sec."] = "Vos attaques ont de fortes chances d'empoisonner la cible, qui subit 8 points de dégâts de Nature toutes les 3 s pendant 9 s.",
    ["Causes Wrath to have a 50% chance to restore 35 Mana."] = "Donne à Colère 50 % de chances de rendre 35 points de mana.",
    ["Chance on harmful spell cast to reduce target's attack power by 60 for 30 sec."] = "Chances quand vous lancez un sort offensif de réduire la puissance d'attaque de la cible de 60 pendant 30 s.",
    ["Chance on harmful spell cast to summon a Zombie Troll of Zum'rah for 20 sec."] = "Chances quand vous lancez un sort offensif d'invoquer un Troll zombie de Zum'rah pendant 20 s.",
    ["Chance on hit to blast the target for 25 to 31 Fire damage."] = "Chances quand vous touchez d'infliger 25 à 31 points de dégâts de Feu à la cible.",
    ["Chance on hit to deal 69 to 81 Arcane damage."] = "Chances quand vous touchez d'infliger 69 à 81 points de dégâts des Arcanes.",
    ["Chance on hit to grant nearby party members 4% increased critical strike chance."] = "Chances quand vous touchez de conférer 4 % de chances de coup critique supplémentaires aux membres du groupe proches.",
    ["Chance on hit to reduce the mana cost of your next spell cast within 10 sec by 24."] = "Chances quand vous touchez de réduire de 24 le coût en mana de votre prochain sort lancé dans les 10 s.",
    ["Chance on hit to restore 32 mana."] = "Chances quand vous touchez de rendre 32 points de mana.",
    ["Restores 3 times as much if attacking an Earth Elemental, Golem, or Titan-forged enemy."] = "Rend trois fois plus contre un élémentaire de terre, un golem ou un ennemi d'origine titanique.",
    ["Chance to strike your ranged target with a Shadowbolt for 13 to 19 Shadow damage."] = "Chances de frapper votre cible à distance d'un Trait de l'ombre, qui subit 13 à 19 points de dégâts d'Ombre.",
    ["Harmful spell casts have a chance to steal 112 life from the target enemy over 8 sec."] = "Vos sorts offensifs ont une chance de dérober 112 points de vie à l'ennemi ciblé en 8 s.",
    ["Melee attacks deal 98 Fire additional damage against Frozen targets."] = "Les attaques de mêlée infligent 98 points de dégâts de Feu supplémentaires aux cibles gelées.",
    ["Reduces all damage taken and chance to be critically hit by 5% in Warsong Gulch."] = "Réduit tous les dégâts subis et les chances de subir un coup critique de 5 % au goulet des Chanteguerres.",
    ["When damaged, has a chance to grant you 1080 armor for 12 sec."] = "Quand vous subissez des dégâts, a une chance de vous conférer 1080 points d'armure pendant 12 s.",
    ["When damaged, has a chance to reduce threat level on all enemies by a small amount for 10 sec."] = "Quand vous subissez des dégâts, a une chance de réduire légèrement votre menace envers tous les ennemis pendant 10 s.",
    ["When struck in combat has a 3% chance to heal you for 60 to 100."] = "Quand vous êtes touché en combat, a 3 % de chances de vous rendre 60 à 100 points de vie.",
    ["When struck in combat has a 5% chance to make you invulnerable to melee damage for 3 sec."] = "Quand vous êtes touché en combat, a 5 % de chances de vous rendre insensible aux dégâts de mêlée pendant 3 s.",
    ["This effect can only occur once every 10 sec."] = "Cet effet ne peut se produire qu'une fois toutes les 10 s.",
    ["While in combat, your healing spells have a chance to grant an ally 300 armor for 10 sec."] = "En combat, vos sorts de soins ont une chance de conférer 300 points d'armure à un allié pendant 10 s.",
    ["Your Frostbolt spells have a 6% chance to restore 50 mana when cast."] = "Vos Éclairs de givre ont 6 % de chances de rendre 50 points de mana quand vous les lancez.",
    ["Your Lacerate hits have a 10% chance to reset the cooldown on Mangle (Bear)."] = "Vos Lacérations ont 10 % de chances de réinitialiser le temps de recharge de Mutilation (ours).",
    ["Your healing spells have a 5% chance to remove 1 Poison effect from the target."] = "Vos sorts de soins ont 5 % de chances de dissiper 1 effet de poison sur la cible.",
    ["Absorbs 600 magical damage. � Lasts 2 min."] = "Absorbe 600 points de dégâts magiques. Dure 2 min.",
    ["Allows you to look far into the distance."] = "Vous permet de voir très loin.",
    ["Attach a lure to your equipped fishing pole, increasing Fishing by 25 for 10 min."] = "Fixe un appât sur votre canne à pêche équipée, ce qui augmente votre compétence en pêche de 25 pendant 10 min.",
    ["Attempts to cure 1 poison effect on the target, and 1 more poison effect every 2 seconds for 8 sec."] = "Tente de guérir 1 effet de poison sur la cible, puis 1 autre toutes les 2 s pendant 8 s.",
    ["Balance the Powers of the Moon, Emerald Dream, and Wild to learn a new ability."] = "Équilibrez les pouvoirs de la Lune, du Rêve d'émeraude et de la Nature sauvage pour apprendre une nouvelle technique.",
    ["Channels a bolt of lightning and hurls it towards all enemies in front of the caster causing 189 to 209 Nature damage."] = "Canalise un éclair et le projette sur tous les ennemis devant le lanceur, qui subissent 189 à 209 points de dégâts de Nature.",
    ["The caster is then surrounded by a barrier of electricit"] = "Le lanceur est ensuite entouré d'une barrière d'électricité.",
    ["Chop nearby Humanoid or Undead corpse in two, restoring 150 Health, 150 Mana, and 15 Rage."] = "Coupe en deux un cadavre d'humanoïde ou de mort-vivant proche, ce qui rend 150 points de vie, 150 points de mana et 15 points de rage.",
    ["Combines Jang'thraze and Sang'thraze to form the mighty sword, Sul'thraze."] = "Combine Jang'thraze et Sang'thraze pour former la puissante épée Sul'thraze.",
    ["Conjures food to eat."] = "Invoque de la nourriture.",
    ["Creates a portal, teleporting group members that use it to Karazhan."] = "Crée un portail qui téléporte à Karazhan les membres du groupe qui l'utilisent.",
    ["Deal 607 Physical damage split between up to 4 nearby enemies."] = "Inflige 607 points de dégâts physiques répartis entre 4 ennemis proches au maximum.",
    ["Deals 25 Fire damage every 5 sec to all nearby enemies for 15 sec."] = "Inflige 25 points de dégâts de Feu toutes les 5 s à tous les ennemis proches pendant 15 s.",
    ["Deals 504 Fire damage over 12 sec."] = "Inflige 504 points de dégâts de Feu en 12 s.",
    ["Demons and Beasts are Rooted in place for 6 sec."] = "Les démons et les bêtes sont immobilisés sur place pendant 6 s.",
    ["Deals 75 Fire damage every 1 sec for 5 sec to all enemies in front of you."] = "Inflige 75 points de dégâts de Feu chaque seconde pendant 5 s à tous les ennemis devant vous.",
    ["Gets you quite drunk too!"] = "Vous rend bien ivre aussi !",
    ["Decrease the armor of target by 50 for 1 min."] = "Réduit l'armure de la cible de 50 pendant 1 min.",
    ["Dig up a grave."] = "Déterre une tombe.",
    ["Usable at Raven Hill Cemetery and Scarlet Monastery Graveyard."] = "Utilisable au cimetière de la colline aux Corbeaux et au cimetière du Monastère écarlate.",
    ["Escape all immobilizing effects."] = "Vous libère de tous les effets d'immobilisation.",
    ["Fear all Demons within 15 yds for 6 sec."] = "Terrifie tous les démons à moins de 15 mètres pendant 6 s.",
    ["Gain the ability to walk on water for 5 min.Attacking or taking damage will cancel this effect."] = "Vous permet de marcher sur l'eau pendant 5 min. Attaquer ou subir des dégâts annule cet effet.",
    ["Heal your pet for 450 to 750."] = "Rend 450 à 750 points de vie à votre familier.",
    ["Increase Rage by 30."] = "Augmente la rage de 30.",
    ["Increase experience gained from slaying Undead by 10% for 5 min."] = "Augmente de 10 % l'expérience gagnée en tuant des morts-vivants pendant 5 min.",
    ["Increase your run speed by 60% for 10 sec, but deals 100 to 500 damage and drains 100 to 500 mana every 2 seconds."] = "Augmente votre vitesse de course de 60 % pendant 10 s, mais inflige 100 à 500 points de dégâts et draine 100 à 500 points de mana toutes les 2 s.",
    ["This effect is doubled in Volcanic areas."] = "Cet effet est doublé dans les zones volcaniques.",
    ["Increases Fire resistance by 33 and absorbs 465 Fire damage. � Lasts 15 sec."] = "Augmente la résistance au Feu de 33 et absorbe 465 points de dégâts de Feu. Dure 15 s.",
    ["Increases all Resistances by 10 and grants Immunity to Fear for 30 sec."] = "Augmente toutes les résistances de 10 et rend insensible à la peur pendant 30 s.",
    ["Increases damage and healing done by magical spells and effects by up to 130 for 20 sec."] = "Augmente les dégâts et les soins prodigués par les sorts et effets magiques de 130 au maximum pendant 20 s.",
    ["Increases healing done by the next 5 spells by up to 450 for 30 sec."] = "Augmente les soins prodigués par vos 5 prochains sorts de 450 au maximum pendant 30 s.",
    ["Increases your Block chance by 8% for 15 sec."] = "Augmente vos chances de blocage de 8 % pendant 15 s.",
    ["This effect is doubled in Strongholds and Cities."] = "Cet effet est doublé dans les places fortes et les capitales.",
    ["Increases your attack speed by 50% for 30 sec."] = "Augmente votre vitesse d'attaque de 50 % pendant 30 s.",
    ["Increases your chance to Dodge by 3% for 20 sec."] = "Augmente vos chances d'esquive de 3 % pendant 20 s.",
    ["Increases your critical strike chance with all spells and attacks by 5% for 20 sec or until you deal a non-periodic critical effect."] = "Augmente vos chances de coup critique avec tous les sorts et attaques de 5 % pendant 20 s, ou jusqu'à ce que vous infligiez un effet critique non périodique.",
    ["Increases your effective stealth detection level by 3 for 10 sec, then reduces your effective stealth detection level by 6 for 20 sec."] = "Augmente votre niveau effectif de détection du camouflage de 3 pendant 10 s, puis le réduit de 6 pendant 20 s.",
    ["Increases your melee and ranged attack power by 280. � Effect lasts for 20 sec."] = "Augmente votre puissance d'attaque en mêlée et à distance de 280. L'effet dure 20 s.",
    ["Lets you walk on water for 1 min."] = "Vous permet de marcher sur l'eau pendant 1 min.",
    ["Marks a target for delivery."] = "Marque une cible pour une livraison.",
    ["After landing 6 to 8 spells or attacks, deal 467 Fire damage."] = "Après 6 à 8 sorts ou attaques réussis, inflige 467 points de dégâts de Feu.",
    ["Number of spells or attacks is halved in Snowy areas."] = "Le nombre de sorts ou d'attaques est réduit de moitié dans les zones enneigées.",
    ["Melee attacks deal an additional 7 Fire damage for 30 sec."] = "Les attaques de mêlée infligent 7 points de dégâts de Feu supplémentaires pendant 30 s.",
    ["Page Everlook Emergency Services for a Parachute-Priest that will assist in healing allies for 15 sec."] = "Appelle les services d'urgence de Long-guet pour un prêtre parachutiste qui aide à soigner vos alliés pendant 15 s.",
    ["Perform a Propellerstorm, reducing your fall speed for 15 sec and dealing 100% weapon damage to nearby enemies when you land."] = "Exécute une tempête d'hélices, ce qui réduit votre vitesse de chute pendant 15 s et inflige 100 % des dégâts de l'arme aux ennemis proches à l'atterrissage.",
    ["Purifies the friendly target, removing 1 disease effect and 1 poison effect."] = "Purifie la cible amie et dissipe 1 effet de maladie et 1 effet de poison.",
    ["Raise the severed head of Roogug, Horrifying and Silencing all Swine within 15 yds for 5 sec."] = "Brandit la tête tranchée de Roogug, qui terrifie et réduit au silence tous les porcins à moins de 15 mètres pendant 5 s.",
    ["Reduces your fall speed for 10 sec."] = "Réduit votre vitesse de chute pendant 10 s.",
    ["Removes existing Immobilizing effects and makes you immune to Immobilizing effects for 5 sec."] = "Dissipe les effets d'immobilisation en cours et vous rend insensible à l'immobilisation pendant 5 s.",
    ["Restores 1293 mana over 27 sec. � Must remain seated while drinking."] = "Rend 1293 points de mana en 27 s. Vous devez rester assis pendant que vous buvez.",
    ["Can only be used at 10% health."] = "Utilisable uniquement à 10 % de vie.",
    ["Slice open and gather from a target Copper, Tin, Silver, or Iron Vein (does not require Mining)."] = "Ouvre un filon de cuivre, d'étain, d'argent ou de fer ciblé et en récolte le contenu (ne nécessite pas Minage).",
    ["Slows nearby enemies by 50% for 10 sec, increased to 80% in Desert areas."] = "Ralentit les ennemis proches de 50 % pendant 10 s, 80 % dans les zones désertiques.",
    ["Stuns target Undead for 6 sec."] = "Étourdit le mort-vivant ciblé pendant 6 s.",
    ["Stuns target Worgen for 4 sec."] = "Étourdit le worgen ciblé pendant 4 s.",
    ["Summons a tracking hound that will protect you for 3 min."] = "Invoque un chien pisteur qui vous protège pendant 3 min.",
    ["Weakens the servants of Razelikh the Defiler."] = "Affaiblit les serviteurs de Razelikh le Profanateur.",
    ["Must be within close proximity of the target to activate."] = "Vous devez être tout près de la cible pour l'activer.",
    ["As my understanding of Arugal's magic grows so does my disdain for the hapless fool."] = "Plus je comprends la magie d'Arugal, plus je méprise ce pauvre fou.",
    ["I am close to completing my research on his so called remedy."] = "Je suis sur le point d'achever mes recherches sur son prétendu remède.",
    ["Edwin VanCleef must be assassinated."] = "Edwin VanCleef doit être assassiné.",
    ["While it saddens me to condemn any man to a death sentence, it is for the greater good of the people of Westfall that VanCleef is laid to rest once and for all."] = "Même s'il m'attriste de condamner un homme à mort, c'est pour le bien du peuple de la marche de l'Ouest que VanCleef doit être mis hors d'état de nuire une fois pour toutes.",
    ["Here is the final challenge that I will put forth."] = "Voici le dernier défi que je vous lance.",
    ["We've been tracking an elusive tiger for weeks."] = "Voilà des semaines que nous pistons un tigre insaisissable.",
    ["I draw my power - my will to continue living and breathing - from the unmitigated hatred I have for the Scourge and all that they have done."] = "Je tire ma force, ma volonté de continuer à vivre et à respirer, de la haine absolue que j'éprouve pour le Fléau et tout ce qu'il a fait.",
    ["I must warn you, this matter must stay between us."] = "Je dois vous prévenir : cette affaire doit rester entre nous.",
    ["The satyr are enough of an embarrassment to us already, and this one is much too close to home."] = "Les satyres sont déjà une honte suffisante pour nous, et celui-ci est bien trop proche de chez nous.",
    ["Prospector Whelgar now holds the original fossil at his site in the Wetlands."] = "Le prospecteur Whelgar détient maintenant le fossile original sur son site des Paluns.",
    ["When I discovered the Stone of Relu, I believed it to be the key to unlocking the mystery of the fossil."] = "Quand j'ai découvert la Pierre de Relu, j'ai cru qu'elle était la clé du mystère du fossile.",
    ["So the prospector wants to send the mysterious fossil to the Explorers' League in Darnassus?"] = "Alors le prospecteur veut envoyer le mystérieux fossile à la Ligue des explorateurs à Darnassus ?",
    ["I don't feel right leaving Darkshore without him."] = "Je ne me sens pas de quitter Sombrivage sans lui.",
    ["Strength has left me."] = "Mes forces m'ont abandonné.",
    ["Your help is needed!"] = "Nous avons besoin de votre aide !",
    ["Long ago this site was a great temple of Elune."] = "Il y a longtemps, ce lieu était un grand temple d'Élune.",
    ["But misfortune led to ruin when the corruption of an Old God seeped up from beneath the earth and tainted the sacred Moon Well."] = "Mais le malheur l'a mené à la ruine quand la corruption d'un Dieu très ancien a suinté des profondeurs et souillé le puits de lune sacré.",
    ["This Twilight's Hammer follower cannot be allowed to complete his plan."] = "On ne peut pas laisser ce disciple du Marteau du crépuscule mener son plan à bien.",
    ["The Twilight's Hammer do not understand the spirits of nature."] = "Le Marteau du crépuscule ne comprend pas les esprits de la nature.",
    ["They believe in the Old Gods--creatures of chaos and destruction that were long ago defeated."] = "Ils croient aux Dieux très anciens, des créatures de chaos et de destruction vaincues il y a bien longtemps.",
    ["This shard holds great secrets; it is the pure essence of the Emerald Dream."] = "Cet éclat renferme de grands secrets : c'est l'essence pure du Rêve d'émeraude.",
    ["However, what I see in this shard is not a dream; one would call this sort of a vision a nightmare."] = "Pourtant, ce que je vois dans cet éclat n'est pas un rêve : une telle vision, on l'appellerait plutôt un cauchemar.",
    ["We believe they are hiding out in the Dagger Hills, plotting their next move."] = "Nous pensons qu'ils se cachent dans les collines de la Dague, à préparer leur prochain coup.",
    ["Slay the wretches in the name of The People's Militia."] = "Tuez ces misérables au nom de la Milice du peuple.",
    ["While I traveled on the road to meet Whelgar, I was attacked by raptors and the relic was lost."] = "Alors que je faisais route pour rejoindre Whelgar, des raptors m'ont attaqué et la relique a été perdue.",
    ["(be aware that some vendors sell items at random)"] = "(attention, certains marchands vendent leurs objets de façon aléatoire)",
    ["Bought from Rune Broker in Stormwind, Ironforge, Darnassus, Elwynn Forest, Dun Morogh, and Teldrassil."] = "Vendu par le courtier en runes à Hurlevent, Forgefer, Darnassus, dans la forêt d'Elwynn, à Dun Morogh et à Teldrassil.",
    ["Bought from Rune Broker in Orgrimmar, Thunder Bluff, Undercity, Durotar, Mulgore, and Tirisfal Glades."] = "Vendu par le courtier en runes à Orgrimmar, aux Pitons-du-Tonnerre, à Fossoyeuse, en Durotar, en Mulgore et dans les clairières de Tirisfal.",
    ["Bought from Rune Broker in Stormwind, Ironforge, Darnassus, Elwynn Forest, Dun Morogh, and Teldrassil, and in Orgrimmar, Thunder Bluff, Undercity, Durotar, Mulgore, and Tirisfal Glades."] = "Vendu par le courtier en runes à Hurlevent, Forgefer, Darnassus, dans la forêt d'Elwynn, à Dun Morogh et à Teldrassil, ainsi qu'à Orgrimmar, aux Pitons-du-Tonnerre, à Fossoyeuse, en Durotar, en Mulgore et dans les clairières de Tirisfal.",
}) do sentences[k] = v end
